INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (17540,'17008','fortaleza','Alcázar de los Reyes Cristianos','Siglo XIV (1328). Colosal palacio fortificado e hito de la arquitectura civil-militar de la Corona de Castilla, mandado edificar por Alfonso XI sobre los restos del palacio califal omeya a orillas del Guadalquivir. Presenta planta rectangular regular amurallada de sillería caliza compacta limpia de gran espesor flanqueada por cuatro grandes torres señoriales cuadradas y cilíndricas (la de los Leones, del Homenaje, de la Inquisición y de la Paloma), con adarves almenados góticos y estanques.',NULL,NULL,NULL,'articulo_web',NULL,NULL,NULL,NULL,'2026-06-06');
