INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85600,'43001','Campings','Camping Albarracín','Situado a un kilómetro de uno de los pueblos más bonitos de España. Cuenta con una altitud idónea para disfrutar de noches frescas en verano y es el campamento base mundial para los aficionados a la escalada en bloque (búlder)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
