INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85617,'30020','Campings','Camping Fuente','Su gran elemento diferenciador es su espectacular piscina de agua termal minero-medicinal que brota de manera natural a 36°C, lo que lo convierte en un destino de relax absoluto durante los meses más fríos',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85618,'21018','Campings','Camping Gran Zarautz, Camping Talaimendi','El Gran Zarautz está ubicado de forma espectacular sobre una colina con vistas panorámicas a la playa de Zarautz (meca del surf). Cuenta con parcelas llanas de césped y un ambiente deportivo inmejorable',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85619,'20061','Campings','Camping Orio','Emplazado en la misma desembocadura de la ría de Orio y a pie de playa, cuenta con excelentes instalaciones deportivas y una piscina muy cuidada',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85620,'47011','Campings','Camping Portuondo','Ubicado en plena Reserva de la Biosfera de Urdaibai, con vistas espectaculares a la famosa ola izquierda de Mundaka. Su restaurante de cocina vasca es un gran referente en la zona',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85621,'31167','Campings','Camping El Molino','Un complejo familiar de gran tamaño que cuenta con piscina cubierta climatizada, toboganes acuáticos exteriores, embarcadero propio en el río Arga y una gran oferta de animación',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85622,'31027','Campings','Camping Eco-Arbizu','Diseñado bajo criterios de bioconstrucción y sostenibilidad ambiental. Ofrece bungalows bioclimáticos, piscina de arena natural y unas vistas imponentes a la Sierra de Urbasa',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85623,'31185','Campings','Camping Osate','Camping de montaña humilde y acogedor a las puertas del Valle de Salazar, ideal para los senderistas que buscan explorar la Selva de Irati de forma pura',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85624,'10037','Campings','Camping Ciudad de Cáceres','Un camping único en España: destaca porque cada una de sus parcelas dispone de un baño propio, privado e individual con ducha dentro de la misma parcela. Ideal para visitar el casco histórico medieval',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85625,'06016','Campings','Camping Agua de Luna','Ubicado en plena dehesa extremeña del sur. Cuenta con piscina, buenas instalaciones de restauración orientadas al producto ibérico local y un ambiente idóneo para el descanso de paso',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
