INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85630,'38027','Campings','Zona de Acampada de la Caldera de Taburiente','Situada en el mismísimo corazón del Parque Nacional. Es un espacio puramente forestal y de montaña, accesible únicamente a pie tras una ruta de senderismo. Cuenta con aseos básicos y requiere permiso previo obligatorio, ofreciendo una experiencia de pernocta bajo uno de los cielos más limpios del planeta',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85631,'40170','Campings','Camping Riaza','El referente absoluto de la provincia. Cuenta con unas instalaciones modernas, parcelas muy llanas y cuidadas, piscina, excelentes pistas polideportivas y unos bungalows de alta calidad, ideales tanto para el verano como para la temporada de esquí en La Pinilla',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85632,'40194','Campings','Camping Acueducto','Un camping de corte urbano y muy funcional. Su gran fuerte es la localización, ya que cuenta con una parada de autobús directo en la entrada que te deja en el centro histórico y el acueducto romano en pocos minutos',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85633,'40040','Campings','Camping Hoces del Duratón','Rodeado de un inmenso bosque de pinos y muy cercano al Parque Natural de las Hoces del Río Duratón, es perfecto para los amantes del piragüismo y el avistamiento de buitres leonados',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85634,'05041','Campings','Camping Valle del Alberche','Ubicado en un entorno natural precioso junto al río Alberche, con zonas de piscinas naturales aptas para el baño. Cuenta con buenas sombras y un ambiente muy familiar los fines de semana',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85635,'05163','Campings','Camping Navaluenga','Instalaciones tradicionales de montaña muy vinculadas al disfrute de la Sierra de Gredos, con parcelas de césped bien cuidadas',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85636,'05105','Campings','Camping Gredos','Situado a gran altitud, en plena entrada a la Plataforma de Gredos. Es un camping puramente de montaña, muy fresco en verano y con un entorno forestal idílico de pinos silvestres',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85637,'37313','Campings','Camping Vega de Francia','Ubicado en el corazón del Parque Natural de Las Batuecas - Sierra de Francia. Destaca por su tranquilidad, su vegetación exuberante y su cercanía al río Alagón',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85638,'37011','Campings','Camping Regio','Un complejo clásico de gran tamaño integrado en un recinto hotelero. Cuenta con dos piscinas grandes, excelentes conexiones de autobús al centro de Salamanca y parcelas con buena sombra artificial',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
