INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85644,'09289','Campings','Camping Arlanza','Emplazado en un pinar inmenso de la Sierra de la Demanda. Ofrece una desconexión absoluta, temperaturas nocturnas muy frescas en verano e instalaciones de madera muy acogedoras',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
