INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85651,'47165','Campings','Camping El Astral','Es el gran referente de la provincia. Un camping de primera categoría, con una limpieza impecable, parcelas de césped muy cuidadas, piscina y una atención al cliente sobresaliente. Muy utilizado como punto de descanso estratégico para rutas norte-sur por la autovía',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85652,'16078','Campings','Camping Caravaning Cuenca','Es el más grande e importante de la provincia. Situado en un denso pinar junto al río Júcar, a solo 5 minutos de las Casas Colgadas. Cuenta con piscina, campos de deporte, restaurante de cocina manchega y parcelas llanas con excelente sombra natural',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85653,'16053','Campings','Camping Soleia d''en Pol','Ubicado en plena Serranía de Cuenca, cerca del nacimiento del río Cuervo y del Parque Cinegético de El Hosquillo. Ideal para el descanso y el senderismo puro de montaña',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85654,'13014','Campings','Camping Los Molinos','Situado en el corazón del Parque Natural de las Lagunas de Ruidera. Es el gran referente de la provincia por su acceso directo a las zonas de baño y cascadas, ofreciendo parcelas muy sombreadas, piscina y alquiler de kayaks',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
