INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85659,'02057','Campings','Camping Montesinos','Comparte el entorno del Parque Natural de las Lagunas de Ruidera en su vertiente albaceteña, muy valorado por su tranquilidad y cercanía a la famosa Cueva de Montesinos citada en el Quijote',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
