INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85661,'26071','Campings','Camping de Haro','El referente absoluto de la comunidad, situado en la capital del vino de Rioja. Cuenta con unas instalaciones impecables, piscina, restaurante de alta calidad y parcelas de césped muy cuidadas junto al río Tirón. Perfecto para hacer rutas por las bodegas del Barrio de la Estación',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85662,'26043','Campings','Camping Dehesa de Canyat','Un camping moderno, muy tranquilo, rodeado de campos y perfecto para explorar tanto la ruta de los monasterios (San Millán de la Cogolla) como los paisajes del valle del Oja',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85663,'39095','Campings','Camping El Rosal, Camping Las Arenas','Ubicados en la desembocadura de las rías de Tina Mayor y Tina Menor, justo en el límite con Asturias. Destacan por sus impresionantes parcelas situadas sobre acantilados y bosques de pinos que mueren en playas salvajes, ideales para el descanso absoluto',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
