INSERT OR IGNORE INTO entidades (id,codigo_ine,tipo,nombre,descripcion,latitud,longitud,foto_url,fuente,sello_oficial,nivel_sello,wiki_url,osm_id,fecha_ingesta) VALUES (85665,'39037','Campings','Camping Liérganes','Camping de corte tradicional con un entorno verde bellísimo a un paso del casco histórico medieval de Liérganes (famoso por la leyenda del Hombre Pez). Cuenta con conexiones de tren directo a Santander',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-11');
